/* ========================================================================
   PearisticOS Dock sizing fix (2026-10-09)
   Count-responsive shelf and viewport-responsive icons share one measurement.
   Overrides older fixed-width rules, including mobile and desktop overrides.
   ======================================================================== */
#dock.dock {
  --pear-dock-width: 380px;
  --pear-dock-icon: 78px;
  --pear-dock-height: 106px;
  --pear-dock-gap: 8px;
  --pear-dock-pad-x: 12px;
  --pear-dock-pad-y: 12px;
  box-sizing: border-box !important;
  width: var(--pear-dock-width) !important;
  max-width: calc(100% - 16px) !important;
  min-width: 0 !important;
  height: var(--pear-dock-height) !important;
  min-height: 0 !important;
  padding: var(--pear-dock-pad-y) var(--pear-dock-pad-x) !important;
  gap: var(--pear-dock-gap) !important;
  display: flex !important;
  justify-content: flex-start !important;
  align-items: center !important;
  flex-wrap: nowrap !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
  scrollbar-width: none;
  transition: width .18s ease, height .18s ease, opacity .24s var(--ease), transform .24s var(--ease) !important;
}
#dock.dock::-webkit-scrollbar { display: none; }
#dock.dock > .app-icon {
  box-sizing: border-box !important;
  flex: 0 0 var(--pear-dock-icon) !important;
  width: var(--pear-dock-icon) !important;
  min-width: var(--pear-dock-icon) !important;
  max-width: var(--pear-dock-icon) !important;
  height: var(--pear-dock-icon) !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  justify-content: center !important;
}
#dock.dock > .app-icon > .app-tile {
  box-sizing: border-box !important;
  display: grid;
  width: var(--pear-dock-icon) !important;
  min-width: 0 !important;
  max-width: var(--pear-dock-icon) !important;
  height: var(--pear-dock-icon) !important;
  min-height: 0 !important;
  max-height: var(--pear-dock-icon) !important;
  aspect-ratio: 1 / 1 !important;
  border-radius: calc(var(--pear-dock-icon) * .23) !important;
}
#dock.dock > .app-icon > .app-name { display: none !important; }
#dock.dock > .app-icon .system-app-icon {
  display: block;
  width: 100% !important;
  height: 100% !important;
  max-width: 100% !important;
  max-height: 100% !important;
  object-fit: contain;
}

/* PearisticOS fullscreen / windowed layout stability (2026-10-09).
   Keep icon corners proportional, and prevent a stretched CSS grid from
   increasing the vertical distance between app rows after resize. */
.home-icon-page .app-tile,
#dock.dock > .app-icon > .app-tile {
  border-radius:22.37% !important;
  aspect-ratio:1 / 1 !important;
}
.home-icon-page .app-tile > .system-app-icon,
#dock.dock > .app-icon > .app-tile > .system-app-icon {
  border-radius:inherit !important;
}
.normal-home-grid {
  grid-template-rows:repeat(var(--session-home-rows,3), var(--pear-normal-row-height,120px)) !important;
  row-gap:var(--pear-normal-row-gap,48px) !important;
  align-content:start !important;
  padding-top:var(--pear-normal-top-padding,28px) !important;
}

/* Use the calculated row gap even in desktop mode. Older 2.5 rules
   otherwise force a constant 45px gap and can hide the bottom row. */
#home .home-icon-page .normal-home-grid {
  grid-template-columns:repeat(var(--session-home-columns,4),minmax(0,1fr))!important;
  grid-template-rows:repeat(var(--session-home-rows,3),var(--pear-normal-row-height,120px))!important;
  column-gap:var(--stable-home-column-gap,24px)!important;
  row-gap:var(--pear-normal-row-gap,18px)!important;
  align-content:start!important;
  padding-top:var(--pear-normal-top-padding,28px)!important;
}
#home .home-icon-page .normal-home-grid > .app-icon {
  width:100%!important;
  max-width:none!important;
}
#home .home-icon-page .infinite-home-grid {
  grid-template-columns:repeat(var(--session-home-columns,4),minmax(0,1fr))!important;
  column-gap:var(--stable-home-column-gap,24px)!important;
  row-gap:var(--stable-home-row-gap,18px)!important;
}

const area=$('#homeArea');if(!area)return;
const grid=currentSessionGrid();
const width=Math.max(280,area.clientWidth);
const height=Math.max(180,area.clientHeight);
const rows=Math.max(1,grid.rows);
const maxGridWidth=Math.min(width,grid.columns*190);
const columnGap=Math.max(8,Math.min(30,maxGridWidth/(grid.columns*8.5)));
const cellWidth=(maxGridWidth-columnGap*(grid.columns-1))/grid.columns;

// Size icons from column width, not from the height of the browser toolbar.
// A shorter window gives up extra space BETWEEN rows first, instead of
// shrinking the icons and increasing their perceived corner roundness.
const preferredIcon=Math.max(44,Math.min(116,cellWidth*.66));
const topPadding=Math.min(28,Math.max(8,height*.055));
const bottomPadding=12;
const labelAllowance=30; // Label + gap; prevents overlap and truncation.
const minimumGap=8;
const desiredGap=Math.min(94,Math.max(35,preferredIcon*.92));
// Empty capacity rows must not shrink the icons or consume row spacing.
// Re-evaluate when Home is rebuilt after adding/removing an app.
const populatedRows=Math.max(1,...Array.from(
  document.querySelectorAll('.normal-home-grid'),
  gridEl=>Math.ceil(gridEl.querySelectorAll(':scope > .app-icon').length / grid.columns)
));
const usedRows=Math.min(rows,populatedRows);
const fitLimit=(height-topPadding-bottomPadding-usedRows*labelAllowance-
                Math.max(0,usedRows-1)*minimumGap)/usedRows;
const iconSize=Math.max(32,Math.min(preferredIcon,fitLimit));
const rowHeight=iconSize+labelAllowance;
const freeSpace=height-topPadding-bottomPadding-usedRows*rowHeight;
const rowGap=usedRows===1?0:Math.max(0,Math.min(desiredGap,freeSpace/(usedRows-1)));

const home=$('#home');
home.dataset.gridOrientation=window.innerHeight>window.innerWidth?'portrait':'landscape';
home.dataset.gridRows=String(grid.rows);
home.dataset.gridColumns=String(grid.columns);
home.style.setProperty('--session-home-columns',String(grid.columns));
home.style.setProperty('--session-home-rows',String(grid.rows));
home.style.setProperty('--session-home-grid-max-width',maxGridWidth+'px');
home.style.setProperty('--stable-home-column-gap',columnGap+'px');
home.style.setProperty('--stable-home-row-gap',rowGap+'px');
home.style.setProperty('--stable-home-icon-size',iconSize+'px');
home.style.setProperty('--stable-home-cell-height',rowHeight+'px');
home.style.setProperty('--pear-normal-row-height',rowHeight+'px');
home.style.setProperty('--pear-normal-row-gap',rowGap+'px');
home.style.setProperty('--pear-normal-top-padding',topPadding+'px');

const fullscreenSettingButton=document.createElement('button');
fullscreenSettingButton.type='button';fullscreenSettingButton.id='pearFullscreenSettingsButton';fullscreenSettingButton.className='app-action';
fullscreenSettingButton.textContent=document.fullscreenElement?'Exit fullscreen':'Enter fullscreen';
fullscreenSettingButton.onclick=()=>window.pearToggleFullscreen?.();
addSettingRow($('#systemSet'),'Browser fullscreen','Enter or exit fullscreen mode. Esc also exits.',fullscreenSettingButton);
